import{_ as o,o as t,c as i,a3 as a}from"./chunks/framework.B_jDsKE8.js";const g=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function r(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: decision → alternatives → consequence.</p><h2 id="keyring-default-fail-closed-file-opt-out" tabindex="-1">Keyring default, fail closed; file opt-out <a class="header-anchor" href="#keyring-default-fail-closed-file-opt-out" aria-label="Permalink to &quot;Keyring default, fail closed; file opt-out&quot;">​</a></h2><p><strong>Decision:</strong> <code>TARDIGRADA_IDENTITY_BACKEND</code> selects the store — <code>keyring</code> (default: the platform session secret store, entry <code>tardigrada/age-identity</code>) fails closed when no store is reachable; <code>auto</code> falls back to the keyfile with a stderr note; <code>file</code> never probes the store. An explicit <code>--identity-file</code>/ <code>TARDIGRADA_IDENTITY_FILE</code> pin always means file.</p><p><strong>Alternatives:</strong> file-only (v1); keyring default with silent file fallback; a config file for backend selection.</p><p><strong>Consequence:</strong> the secret leaves the disk on desktop sessions — the keyring unlocks with login, so reads need no prompt and there is no <code>0600</code> file to leak. Fail-closed means headless/CI must opt out explicitly (<code>auto</code> or <code>file</code>) rather than silently diverging onto a keyfile the keyring can&#39;t see — the same semantics cuora adopted. No config file in v1: one env var covers it, and the explicit pin always wins. Keyfiles keep working: <code>file</code>/<code>auto</code> read them (including legacy <code>cuora</code>/<code>arca</code> paths via the shared <code>cuora-identity-file</code> resolution), and <code>init</code> under <code>keyring</code>/<code>auto</code> adopts a keyfile identity into the store instead of orphaning its ciphertext.</p><h2 id="export-import-over-config-coupling" tabindex="-1"><code>export</code>/<code>import</code> over config coupling <a class="header-anchor" href="#export-import-over-config-coupling" aria-label="Permalink to &quot;`export`/`import` over config coupling&quot;">​</a></h2><p><strong>Decision:</strong> cuora interop is &quot;point both tools at the same keyfile&quot; or &quot;move the keyfile&quot; — no cuora-aware verbs, no shared config discovery.</p><p><strong>Alternatives:</strong> tardigrada reads/writes cuora&#39;s config; a <code>tardigrada cuora</code> subcommand family.</p><p><strong>Consequence:</strong> tardigrada manages <em>generic</em> identities — it never learns what vaults, <code>cuora://</code> refs, or envs are. The integration surface stays one file and two env vars; either tool can be swapped without the other noticing.</p><h2 id="payload-bin-not-a-driver-shim" tabindex="-1">Payload bin, not a driver shim <a class="header-anchor" href="#payload-bin-not-a-driver-shim" aria-label="Permalink to &quot;Payload bin, not a driver shim&quot;">​</a></h2><p><strong>Decision:</strong> the <code>tardigrada</code> command ships as a tamias <code>type: files</code> pack whose <code>bins[].payload</code> is the compiled binary staged by <code>scripts/pack.sh</code> — a real binary on PATH.</p><p><strong>Alternatives:</strong> the org&#39;s usual <code>bins[]</code> shim → <code>tamias-driver-*</code> → engine-lib passthrough (cuora/myco shape); a driver crate.</p><p><strong>Consequence:</strong> no shim→driver→engine indirection for a tool this size — one fewer crate, one fewer process, <code>cargo install --path</code> and <code>tamias install</code> both deploy the same artifact. The cost is a per-triple build artifact (<code>tools/bin/&lt;triple&gt;/</code>, gitignored) instead of a portable shim.</p><h2 id="init-never-clobbers-import-overwrites-deliberately" tabindex="-1"><code>init</code> never clobbers; <code>import</code> overwrites deliberately <a class="header-anchor" href="#init-never-clobbers-import-overwrites-deliberately" aria-label="Permalink to &quot;`init` never clobbers; `import` overwrites deliberately&quot;">​</a></h2><p><strong>Decision:</strong> <code>init</code> is idempotent-safe (second run reports the existing recipient); <code>import</code> replaces whatever identity is configured, with no undo.</p><p><strong>Alternatives:</strong> <code>init --force</code>; <code>import</code> to a staging path.</p><p><strong>Consequence:</strong> the dangerous verb is the explicit one — adopting an existing key is a deliberate act, and pointing <code>import</code> at the wrong file is on the operator (SECURITY.md scope note). <code>export</code> refuses bare-stdout under <code>--json</code> for the same reason: a secret inside a JSON envelope invites accidental logging.</p>',18)])])}const f=o(n,[["render",r]]);export{g as __pageData,f as default};
